-- Nested Supabase-driven starter layouts; existing projects/pages unchanged.
alter table public.component_presets add column if not exists children_template jsonb not null default '[]'::jsonb
 check(jsonb_typeof(children_template)='array');
update public.component_presets p
set children_template=case
 when p.component_type in ('form','fieldset','contact-form','newsletter-form','login-panel') then jsonb_build_array(jsonb_build_object('id','preset-form-head','type','heading','props',jsonb_build_object('text',p.label_vi),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb),jsonb_build_object('id','preset-email','type','email-input','props',jsonb_build_object('name','email','placeholder','Email của bạn'),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-message','type','textarea','props',jsonb_build_object('name','message','placeholder','Nội dung của bạn'),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-submit','type','submit-button','props',jsonb_build_object('text','Gửi thông tin','href',''),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb))
 when p.component_type in ('gallery','picture','fashion-gallery','icon-grid') then jsonb_build_array(jsonb_build_object('id','preset-image-1','type','image','props',jsonb_build_object('src','','alt','Ảnh minh họa 1 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-image-2','type','image','props',jsonb_build_object('src','','alt','Ảnh minh họa 2 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-image-3','type','image','props',jsonb_build_object('src','','alt','Ảnh minh họa 3 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb))
 when p.component_type in ('grid','feature-grid','product-grid','portfolio-grid','pricing-grid','dashboard-panel','fashion-lookbook','team-lineup','match-scoreboard') then jsonb_build_array(jsonb_build_object('id','preset-card-1','type','card','props',jsonb_build_object('label','Khối 1'),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children',jsonb_build_array(jsonb_build_object('id','preset-card-1-title','type','h3','props',jsonb_build_object('text','Mục 1 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-card-1-desc','type','paragraph','props',jsonb_build_object('text','Sửa nội dung 1 cho '||lower(p.context_vi)),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb))),jsonb_build_object('id','preset-card-2','type','card','props',jsonb_build_object('label','Khối 2'),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children',jsonb_build_array(jsonb_build_object('id','preset-card-2-title','type','h3','props',jsonb_build_object('text','Mục 2 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-card-2-desc','type','paragraph','props',jsonb_build_object('text','Sửa nội dung 2 cho '||lower(p.context_vi)),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb))),jsonb_build_object('id','preset-card-3','type','card','props',jsonb_build_object('label','Khối 3'),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children',jsonb_build_array(jsonb_build_object('id','preset-card-3-title','type','h3','props',jsonb_build_object('text','Mục 3 · '||p.context_vi),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb),jsonb_build_object('id','preset-card-3-desc','type','paragraph','props',jsonb_build_object('text','Sửa nội dung 3 cho '||lower(p.context_vi)),'style','{"backgroundColor":"#ffffff","color":"#0f172a","fontSize":"16","padding":"12","borderRadius":"12","gap":"9","borderWidth":"1","borderColor":"#e2e8f0"}'::jsonb,'children','[]'::jsonb))))
 when p.component_type in ('game-hud','game-inventory','quest-board','game-menu') then jsonb_build_array(jsonb_build_object('id','preset-heading','type','heading','props',jsonb_build_object('text',p.context_vi||' · '||p.label_vi),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb),jsonb_build_object('id','preset-hud','type','stats','props',jsonb_build_object('text','Giao diện HUD mẫu · '||p.context_vi),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb),jsonb_build_object('id','preset-progress','type','progress','props',jsonb_build_object('value','60','max','100'),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb))
 else jsonb_build_array(jsonb_build_object('id','preset-heading','type','heading','props',jsonb_build_object('text',p.context_vi||' · '||p.label_vi),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb),jsonb_build_object('id','preset-description','type','paragraph','props',jsonb_build_object('text','Chỉnh sửa nội dung cho '||lower(p.context_vi)),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb),jsonb_build_object('id','preset-cta','type','button','props',jsonb_build_object('text','Xem thêm','href','/'),'style',jsonb_build_object('backgroundColor',p.style_override->>'backgroundColor','color',p.style_override->>'color','fontSize','19','padding','12','borderRadius','12','gap','9'),'children','[]'::jsonb)) end
where p.component_type in ('container','section','row','column','grid','flex','stack','card','hero','header','footer','navigation','sidebar','article','main','figure','form','fieldset','gallery','picture','details','dialog-shell','toolbar','feature-grid','product-grid','portfolio-grid','game-hud','game-menu','game-inventory','quest-board','team-lineup','match-scoreboard','fashion-lookbook','mobile-navigation','pricing-grid','testimonial-panel','faq-panel','dashboard-panel','login-panel','landing-banner','contact-form','newsletter-form','icon-grid','fashion-gallery');
